  g2j(gy, gm, gd) {
    const g_d_m = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    const gy2 = (gm > 2) ? (gy + 1) : gy;
    let days = 355666 + (365 * gy) + parseInt((gy2 + 3) / 4, 10) - parseInt((gy2 + 99) / 100, 10) + parseInt((gy2 + 399) / 400, 10) + gd;
    for (let i = 0; i < gm - 1; i++) days += g_d_m[i];
    if (gm > 2 && ((gy % 4 === 0 && gy % 100 !== 0) || gy % 400 === 0)) days++;
    let jy = -1595 + (33 * parseInt(days / 12053, 10));
    days %= 12053;
    jy += 4 * parseInt(days / 1461, 10);
    days %= 1461;
    if (days > 365) { jy += parseInt((days - 1) / 365, 10); days = (days - 1) % 365; }
    let jm, jd;
    if (days < 186) { jm = 1 + parseInt(days / 31, 10); jd = 1 + (days % 31); }
    else { jm = 7 + parseInt((days - 186) / 30, 10); jd = 1 + ((days - 186) % 30); }
    return { jy: jy, jm: jm, jd: jd };
  }

  jIsLeap(jy) {
    const a = jy - ((jy > 0) ? 474 : 473);
    const b = (a % 2820) + 474;
    return (((b + 38) * 682) % 2816) < 682;
  }

  jMonthLen(jy, jm) {
    if (jm <= 6) return 31;
    if (jm <= 11) return 30;
    return this.jIsLeap(jy) ? 30 : 29;
  }

  jMonthNames() {
    return ['فروردین', 'اردیبهشت', 'خرداد', 'تیر', 'مرداد', 'شهریور', 'مهر', 'آبان', 'آذر', 'دی', 'بهمن', 'اسفند'];
  }

  financialFor(s) {
    const period = s.finPeriod || 'monthly';
    const data = this.financialData();
    if (period === 'quarterly' || period === 'yearly') return data[period];

    const now = new Date();
    const jToday = this.g2j(now.getFullYear(), now.getMonth() + 1, now.getDate());

    if (period === 'daily') {
      const jy = s.finSelJY || jToday.jy, jm = s.finSelJM || jToday.jm, jd = s.finSelJD || jToday.jd;
      const dateStr = jy + '-' + jm + '-' + jd;
      let h = 0; for (let i = 0; i < dateStr.length; i++) h = (h * 31 + dateStr.charCodeAt(i)) >>> 0;
      const base = data.daily;
      const mult = 0.6 + (h % 90) / 100;
      const hours = ['۶', '۹', '۱۲', '۱۵', '۱۸', '۲۱', '۲۴'];
      return {
        revenue: Math.round(base.revenue * mult), cost: Math.round(base.cost * mult), orders: Math.max(1, Math.round(base.orders * mult)),
        chart: base.chart.map((b, i) => ({ label: hours[i] || b.label, v: Math.max(1, Math.round(b.v * (0.7 + ((h >> i) % 50) / 100))) })),
        byService: base.byService.map(sv => ({ label: sv.label, value: Math.round(sv.value * mult) })),
      };
    }
    // monthly
    const jy = s.finMonthSelJY || jToday.jy, jm = s.finMonthSelJM || jToday.jm;
    const monthStr = jy + '-' + jm;
    let h = 0; for (let i = 0; i < monthStr.length; i++) h = (h * 31 + monthStr.charCodeAt(i)) >>> 0;
    const base = data.monthly;
    const mult = 0.65 + (h % 80) / 100;
    return {
      revenue: Math.round(base.revenue * mult), cost: Math.round(base.cost * mult), orders: Math.max(3, Math.round(base.orders * mult)),
      chart: base.chart.map((b, i) => ({ label: b.label, v: Math.max(4, Math.round(b.v * (0.7 + ((h >> (i * 2)) % 50) / 100))) })),
      byService: base.byService.map(sv => ({ label: sv.label, value: Math.round(sv.value * mult) })),
    };
  }

