  permRowsFor(staffId, roleId, s, storeKey) {
    const mods = this.moduleLabels();
    const role = this.rolesData().concat(s.customRoles || []).find(r => r.id === roleId) || { full: false, mods: [] };
    const store = storeKey === 'new' ? (s.newStaffPerms || {}) : ((s.staffPermOverrides && s.staffPermOverrides[staffId]) || {});
    return Object.keys(mods).map(mk => {
      const defaultOn = role.full || (role.mods || []).includes(mk);
      const cur = store[mk] || { view: defaultOn, edit: defaultOn, del: role.full };
      const setPerm = (field, val) => this.setState(state => {
        if (storeKey === 'new') {
          const np = { ...(state.newStaffPerms || {}) };
          np[mk] = { ...cur, [field]: val };
          return { newStaffPerms: np };
        }
        const po = { ...(state.staffPermOverrides || {}) };
        po[staffId] = { ...(po[staffId] || {}) };
        po[staffId][mk] = { ...cur, [field]: val };
        return { staffPermOverrides: po };
      });
      return {
        label: mods[mk], view: cur.view, edit: cur.edit, del: cur.del,
        toggleView: e => setPerm('view', e.target.checked),
        toggleEdit: e => setPerm('edit', e.target.checked),
        toggleDel: e => setPerm('del', e.target.checked),
      };
    });
  }

